-- LabQMS 2429 foundation. Non-destructive initial migration.
create extension if not exists pgcrypto;
create type public.account_status as enum ('pending','approved','suspended');
create type public.app_role as enum ('super_admin','lab_admin','quality_manager','chapter_lead','staff','viewer');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.laboratories(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,laboratory_id uuid references public.laboratories(id),email text not null,full_name text,status public.account_status not null default 'pending',role public.app_role not null default 'staff',created_at timestamptz not null default now(),approved_at timestamptz,approved_by uuid references auth.users(id));
create table public.chapters(id smallint primary key check(id between 1 and 12),roman text not null unique,name text not null,created_at timestamptz not null default now());
create table public.criteria(id uuid primary key default gen_random_uuid(),chapter_id smallint not null references public.chapters(id),code text,legal_text text not null default 'Chưa xác minh, cần quản trị viên đối chiếu phụ lục chính thức.',max_score numeric,verification_status text not null default 'unverified' check(verification_status in ('unverified','verified','rejected')),source_url text,source_version text,verified_by uuid references auth.users(id),verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(verification_status <> 'verified' or (verified_by is not null and verified_at is not null and source_url is not null)));
alter table public.organizations enable row level security; alter table public.laboratories enable row level security; alter table public.profiles enable row level security; alter table public.chapters enable row level security; alter table public.criteria enable row level security;
create policy profiles_read_self on public.profiles for select to authenticated using(id=auth.uid());
create policy chapters_read_approved on public.chapters for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='approved'));
create policy criteria_read_approved on public.criteria for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='approved'));
insert into public.chapters(id,roman,name) values
(1,'I','TỔ CHỨC VÀ QUẢN LÝ PHÒNG XÉT NGHIỆM'),(2,'II','QUẢN LÝ TÀI LIỆU VÀ HỒ SƠ'),(3,'III','QUẢN LÝ NHÂN SỰ'),(4,'IV','CUNG CẤP DỊCH VỤ VÀ QUẢN LÝ KHÁCH HÀNG'),(5,'V','QUẢN LÝ TRANG THIẾT BỊ'),(6,'VI','ĐÁNH GIÁ NỘI BỘ'),(7,'VII','QUẢN LÝ MUA SẮM, TRANG THIẾT BỊ, VẬT TƯ, HÓA CHẤT VÀ SINH PHẨM'),(8,'VIII','QUẢN LÝ QUÁ TRÌNH XÉT NGHIỆM'),(9,'IX','QUẢN LÝ THÔNG TIN'),(10,'X','XÁC ĐỊNH SỰ KHÔNG PHÙ HỢP, HÀNH ĐỘNG KHẮC PHỤC VÀ HÀNH ĐỘNG PHÒNG NGỪA'),(11,'XI','CẢI TIẾN LIÊN TỤC'),(12,'XII','CƠ SỞ VẬT CHẤT VÀ AN TOÀN') on conflict(id) do update set roman=excluded.roman,name=excluded.name;
